{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C25"],
      "claim": "Vilazodone, an indole-based drug with a basic amine, has an absolute oral bioavailability of 72% in humans, supporting high F for the query's indole/basic-amine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Mizolastine, a basic-amine-containing drug, has an absolute oral bioavailability of 65% in healthy volunteers, supporting high F for a similarly ionizable basic amine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Encainide, a basic amine drug with first-pass metabolism, has an absolute oral bioavailability of 32 ± 7% in normal subjects, above the 20% threshold and supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "L-5-Hydroxytryptophan, an indole-containing molecule, has an absolute bioavailability of 49% in volunteers, supporting high F for the indole core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Bepridil, a basic amine drug, has an oral bioavailability of 62% in healthy volunteers, supporting high F for a lipophilic basic amine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Nabumetone's active metabolite has an absolute bioavailability of 38%, supporting high F for a moderately lipophilic, non-acidic oral drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Ilomastat, a peptidomimetic MMP inhibitor with an indole and hydroxamic acid, showed poor oral bioavailability; this is contradictory but has limited structural analogy to the query due to its peptide-like and hydroxamate features.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most highly transferable experimental analogues show oral bioavailability values at or above 20%, including indole- and basic-amine-containing drugs (32–72%). The only clearly low-bioavailability analogue is a peptidomimetic hydroxamate with limited structural resemblance. Therefore the query is predicted to have high oral bioavailability at the F ≥ 20% threshold.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query or a close triptan analogue such as sumatriptan.",
    "First-pass metabolism, especially MAO-mediated metabolism of the dimethylaminoethyl side chain, was not directly assessed.",
    "No human pharmacokinetic data are available for the exact pyrrolidine sulfonamide variant."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

